describe('Save Search Query Feature', () => {
  beforeEach(() => {
    cy.visit('/');
    cy.get('[data-testid="search-input"]').should('be.visible');
  });

  it('should save a search query successfully', () => {
    const searchQuery = 'cypress automation testing';

    cy.get('[data-testid="search-input"]').type(searchQuery);
    cy.get('[data-testid="search-button"]').click();

    cy.get('[data-testid="save-search-btn"]').should('be.visible').click();

    cy.get('[data-testid="save-search-modal"]').should('be.visible');
    cy.get('[data-testid="save-search-name-input"]').type('My Test Search');
    cy.get('[data-testid="confirm-save-btn"]').click();

    cy.get('[data-testid="success-message"]').should('contain', 'Search saved successfully');
    cy.get('[data-testid="save-search-modal"]').should('not.exist');
  });

  it('should display saved searches in the sidebar', () => {
    const searchQuery = 'test query';
    const searchName = 'Saved Test Query';

    cy.get('[data-testid="search-input"]').type(searchQuery);
    cy.get('[data-testid="search-button"]').click();
    cy.get('[data-testid="save-search-btn"]').click();
    cy.get('[data-testid="save-search-modal"]').should('be.visible');
    cy.get('[data-testid="save-search-name-input"]').type(searchName);
    cy.get('[data-testid="confirm-save-btn"]').click();

    cy.get('[data-testid="saved-searches-section"]').should('be.visible');
    cy.get('[data-testid="saved-search-item"]').should('contain', searchName);
  });

  it('should prevent saving with empty search name', () => {
    const searchQuery = 'test query';

    cy.get('[data-testid="search-input"]').type(searchQuery);
    cy.get('[data-testid="search-button"]').click();
    cy.get('[data-testid="save-search-btn"]').click();

    cy.get('[data-testid="save-search-modal"]').should('be.visible');
    cy.get('[data-testid="save-search-name-input"]').should('have.value', '');
    cy.get('[data-testid="confirm-save-btn"]').should('be.disabled');
  });

  it('should load a saved search when clicked', () => {
    const searchQuery = 'original search';
    const searchName = 'My Saved Search';

    cy.get('[data-testid="search-input"]').type(searchQuery);
    cy.get('[data-testid="search-button"]').click();
    cy.get('[data-testid="save-search-btn"]').click();
    cy.get('[data-testid="save-search-name-input"]').type(searchName);
    cy.get('[data-testid="confirm-save-btn"]').click();

    cy.get('[data-testid="search-input"]').clear();
    cy.get('[data-testid="search-input"]').should('have.value', '');

    cy.get('[data-testid="saved-search-item"]').contains(searchName).click();

    cy.get('[data-testid="search-input"]').should('have.value', searchQuery);
    cy.get('[data-testid="search-results"]').should('be.visible');
  });

  it('should handle duplicate saved search names gracefully', () => {
    const searchQuery = 'test query';
    const duplicateName = 'Duplicate Search';

    cy.get('[data-testid="search-input"]').type(searchQuery);
    cy.get('[data-testid="search-button"]').click();
    cy.get('[data-testid="save-search-btn"]').click();
    cy.get('[data-testid="save-search-name-input"]').type(duplicateName);
    cy.get('[data-testid="confirm-save-btn"]').click();
    cy.get('[data-testid="success-message"]').should('be.visible');

    cy.get('[data-testid="search-input"]').clear().type('another query');
    cy.get('[data-testid="search-button"]').click();
    cy.get('[data-testid="save-search-btn"]').click();
    cy.get('[data-testid="save-search-name-input"]').type(duplicateName);
    cy.get('[data-testid="confirm-save-btn"]').click();

    cy.get('[data-testid="error-message"]').should('contain', 'already exists');
  });

  it('should delete a saved search', () => {
    const searchQuery = 'test query';
    const searchName = 'Search to Delete';

    cy.get('[data-testid="search-input"]').type(searchQuery);
    cy.get('[data-testid="search-button"]').click();
    cy.get('[data-testid="save-search-btn"]').click();
    cy.get('[data-testid="save-search-name-input"]').type(searchName);
    cy.get('[data-testid="confirm-save-btn"]').click();

    cy.get('[data-testid="saved-search-item"]').contains(searchName).parent().find('[data-testid="delete-search-btn"]').click();
    cy.get('[data-testid="confirm-delete-btn"]').click();

    cy.get('[data-testid="saved-search-item"]').should('not.contain', searchName);
  });
});
